CAPTURE_SHA = "7e641882902da66b0e6de7ccaf5ee475223645f966b15c942b883b66d6027cc0"


class CurrentHorizonInputAssemblyTests(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        # Same decoded compact map as the original focused run, frozen inline.
        cls.captured = json.loads(CAPTURED_FIELD_MAP_JSON)

    def test_actual_historical_values_keep_exact_frame_provenance(self):
        before = copy.deepcopy(self.captured)
        assembly = assemble_current_horizon_input(self.captured)
        rows = {row["target_field"]: row for row in assembly.concrete_values}
        for key, value in {
            "snapshot_revision": 210, "observed_date_raw": 53250960,
            "combat_id": 1291845646, "phase": "pursuit", "phase_raw": 2,
            "phase_day": 3, "base_combat_width": 3076, "final_combat_width": 2460,
            "base_advantage_raw": -500000, "resolved_advantage_raw": 700000,
            "forced_winner_raw": -1, "finalized": False,
        }.items():
            self.assertEqual(rows[key]["value"], value, key)
            self.assertEqual(rows[key]["source_json_pointer"],
                             "/control_before/battle_control_snapshot/" + key)
            self.assertEqual(rows[key]["source_sha256"], CAPTURE_SHA)
        self.assertEqual(rows["attacker"]["value"]["stored_current_fighting_raw"], 353747862)
        self.assertEqual(rows["defender"]["value"]["derived_soft_casualties_raw"], 126883008)
        self.assertEqual(rows["attacker"]["value"]["ordered_armies"][0]["public_cunit_id"], 83886367)
        self.assertEqual(assembly.provenance["frame"]["public_revision"], 14)
        self.assertEqual(assembly.captured_build_identity,
                         {"game_version": None, "executable_sha256": None})
        self.assertEqual(assembly.build_binding["steam_build_id"], 25652598)
        self.assertFalse(any(gap.stage == "binding" for gap in assembly.missing_entries))
        self.assertEqual(assembly.construction_fields["snapshot_source_reference"]["sha256"], CAPTURE_SHA)
        self.assertIsNone(assembly.construction_fields["snapshot"])
        self.assertEqual(self.captured, before)

    def test_incomplete_next_capture_never_invents_operands_or_future_conditions(self):
        partial = {
            "build_binding": copy.deepcopy(self.captured["build_binding"]),
            "capture_provenance": {"path": "caller:incomplete-next-capture", "sha256": None},
            "current_snapshot": {"status": "available", "combat_id": 42},
            "current_snapshot_input_complete": False,
            "active_resume_inputs": None,
            "scenario_inputs": {"entry_events": None},
        }
        assembly = assemble_current_horizon_input(partial)
        values = {row["target_field"]: row["value"] for row in assembly.concrete_values}
        missing = {gap.input_name: gap for gap in assembly.missing_entries}
        self.assertEqual(values, {"combat_id": 42})
        self.assertNotIn("base_advantage_raw", values)
        self.assertNotIn("resolved_advantage_raw", values)
        self.assertIsNone(assembly.construction_fields["snapshot"])
        self.assertIsNone(assembly.construction_fields["backing_components_by_regiment_id"])
        for name in ("complete_normalized_current_snapshot", "current_loss_inputs_v1",
                     "active_counter_inputs_v1", "pursuit_modifier_sides", "draw_state",
                     "admission", "entry_events", "phase_events", "ai_context", "pursuit", "terminal"):
            self.assertIn(name, missing)
            self.assertTrue(missing[name].dto_entry)
            self.assertTrue(missing[name].construction_guidance)
        self.assertEqual(assembly.scenario_inputs, {"entry_events": None})
        self.assertFalse(assembly.current_snapshot_input_complete)
        self.assertEqual(assembly.actual_game_days_advanced, 0)
        self.assertFalse(assembly.native_rng_state_observed)
        self.assertFalse(assembly.actual_next_draw_claimed)
        self.assertFalse(assembly.complete_native_transition)
        self.assertFalse(assembly.complete_monte_carlo)
        self.assertFalse(assembly.win_probability_ready)


if __name__ == "__main__":
    unittest.main(verbosity=2)
